function cleanSource(raw) {
  let t = raw.replace(/\r\n?/g, "\n").replace(/ /g, " ").replace(/\t/g, " ");
  const s = t.search(/\*\*\*\s*START OF (THE|THIS) PROJECT GUTENBERG[^\n]*\n/i);
  if (s >= 0) t = t.slice(t.indexOf("\n", s) + 1);
  const e = t.search(/\*\*\*\s*END OF (THE|THIS) PROJECT GUTENBERG/i);
  if (e >= 0) t = t.slice(0, e);
  t = t.replace(/(\w)-\n(\w)/g, "$1$2");
  const hasBlank = /\n[ ]*\n/.test(t);
  let paras;
  if (hasBlank) paras = t.split(/\n[ ]*\n+/).map((p) => p.replace(/\s*\n\s*/g, " "));
  else paras = t.split("\n");
  paras = paras.map((p) => p.replace(/[ ]{2,}/g, " ").trim()).filter((p) => p && !/^\d{1,4}$/.test(p));
  return paras.join("\n\n");
}
var words = (s) => (s.match(/\S+/g) || []).length;
function segment(text, target = 350) {
  const paras = [];
  for (const p of text.split(/\n\n+/)) {
    if (words(p) <= 600) {
      paras.push(p);
      continue;
    }
    const sents = p.match(/[^.!?…]+[.!?…]+["'”’»)]*\s*|[^.!?…]+$/g) || [p];
    let cur2 = "";
    for (const s of sents) {
      if (cur2 && words(cur2) + words(s) > 400) {
        paras.push(cur2.trim());
        cur2 = "";
      }
      cur2 += s;
    }
    if (cur2.trim()) paras.push(cur2.trim());
  }
  const segs = [];
  let cur = [], n = 0;
  for (const p of paras) {
    const w = words(p);
    if (cur.length && n + w > target) {
      segs.push({ src: cur });
      cur = [];
      n = 0;
    }
    cur.push(p);
    n += w;
  }
  if (cur.length) segs.push({ src: cur });
  return segs;
}
var TRANSLATOR_CORE = `\u0422\u0438 \u2014 \u043C\u0430\u0439\u0441\u0442\u0435\u0440 \u0445\u0443\u0434\u043E\u0436\u043D\u044C\u043E\u0433\u043E \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434\u0443 \u0437 \u0430\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u043E\u0457 \u043D\u0430 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0443 \u0440\u0456\u0432\u043D\u044F \u043D\u0430\u0439\u043A\u0440\u0430\u0449\u0438\u0445 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0438\u0445 \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434\u0430\u0447\u0456\u0432 (\u041C\u0438\u043A\u043E\u043B\u0430 \u041B\u0443\u043A\u0430\u0448, \u0420\u043E\u0441\u0442\u0438\u0441\u043B\u0430\u0432 \u0414\u043E\u0446\u0435\u043D\u043A\u043E, \u041E\u043B\u0435\u043A\u0441\u0430\u043D\u0434\u0440 \u0422\u0435\u0440\u0435\u0445, \u0412\u0456\u043A\u0442\u043E\u0440 \u041C\u043E\u0440\u043E\u0437\u043E\u0432). \u0422\u0432\u0456\u0439 \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434 \u043C\u0430\u0454 \u0447\u0438\u0442\u0430\u0442\u0438\u0441\u044F \u044F\u043A \u043E\u0440\u0438\u0433\u0456\u043D\u0430\u043B\u044C\u043D\u0430 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0430 \u043F\u0440\u043E\u0437\u0430, \u043D\u0430\u043F\u0438\u0441\u0430\u043D\u0430 \u0446\u0438\u043C \u0441\u0430\u043C\u0438\u043C \u0430\u0432\u0442\u043E\u0440\u043E\u043C \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E, \u2014 \u0437 \u0442\u0438\u043C \u0441\u0430\u043C\u0438\u043C \u0433\u043E\u043B\u043E\u0441\u043E\u043C, \u0440\u0438\u0442\u043C\u043E\u043C, \u043D\u0430\u0441\u0442\u0440\u043E\u0454\u043C, \u0456\u0440\u043E\u043D\u0456\u0454\u044E \u0439 \u043E\u0431\u0440\u0430\u0437\u043D\u0456\u0441\u0442\u044E. \u0422\u0438 \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434\u0430\u0454\u0448 \u0434\u0443\u043C\u043A\u0443, \u043E\u0431\u0440\u0430\u0437, \u0442\u043E\u043D \u0456 \u0435\u0444\u0435\u043A\u0442 \u043D\u0430 \u0447\u0438\u0442\u0430\u0447\u0430, \u0430 \u043D\u0435 \u0441\u043B\u043E\u0432\u0430.

\u041E\u0411\u041E\u0412'\u042F\u0417\u041A\u041E\u0412\u0406 \u041D\u041E\u0420\u041C\u0418 \u0423\u041A\u0420\u0410\u0407\u041D\u0421\u042C\u041A\u041E\u0407 \u041C\u041E\u0412\u0418 (\u0423\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0438\u0439 \u043F\u0440\u0430\u0432\u043E\u043F\u0438\u0441 2019 \u0440\u043E\u043A\u0443, \u0441\u0443\u0447\u0430\u0441\u043D\u0430 \u043B\u0456\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043D\u0430 \u043D\u043E\u0440\u043C\u0430):
\u2022 \u0414\u0456\u0430\u043B\u043E\u0433\u0438: \u043A\u043E\u0436\u043D\u0430 \u0440\u0435\u043F\u043B\u0456\u043A\u0430 \u0437 \u043D\u043E\u0432\u043E\u0433\u043E \u0430\u0431\u0437\u0430\u0446\u0443, \u043F\u043E\u0447\u0438\u043D\u0430\u0454\u0442\u044C\u0441\u044F \u0437 \u0442\u0438\u0440\u0435 \xAB\u2014 \xBB. \u0421\u043B\u043E\u0432\u0430 \u0430\u0432\u0442\u043E\u0440\u0430 \u043F\u0456\u0441\u043B\u044F \u0440\u0435\u043F\u043B\u0456\u043A\u0438: \xAB\u2014 \u0425\u043E\u0434\u0456\u043C\u043E, \u2014 \u0441\u043A\u0430\u0437\u0430\u0432 \u0432\u0456\u043D.\xBB; \u043F\u0435\u0440\u0435\u0434 \u0440\u0435\u043F\u043B\u0456\u043A\u043E\u044E: \xAB\u0412\u0456\u043D \u0441\u043A\u0430\u0437\u0430\u0432: \u2014 \u0425\u043E\u0434\u0456\u043C\u043E.\xBB \u0410\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u0456 \u043B\u0430\u043F\u043A\u0438 \u0432 \u0434\u0456\u0430\u043B\u043E\u0433\u0430\u0445 \u043D\u0435 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u044E\u0442\u044C\u0441\u044F. \u0426\u0438\u0442\u0430\u0442\u0438 \u0439 \u043D\u0430\u0437\u0432\u0438 \u2014 \u043B\u0430\u043F\u043A\u0438 \xAB\u044F\u043B\u0438\u043D\u043A\u0438\xBB, \u0432\u043A\u043B\u0430\u0434\u0435\u043D\u0456 \u2014 \u201E\u043B\u0430\u043F\u043A\u0438\u201C.
\u2022 \u0412\u043B\u0430\u0441\u043D\u0456 \u0456\u043C\u0435\u043D\u0430: \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0439 \u0444\u043E\u043D\u0435\u0442\u0438\u0447\u043D\u043E \u0437\u0430 \u043F\u0440\u0430\u0432\u043E\u043F\u0438\u0441\u043E\u043C 2019 \u0456 \u0443\u0441\u0442\u0430\u043B\u0435\u043D\u043E\u044E \u0442\u0440\u0430\u0434\u0438\u0446\u0456\u0454\u044E (h \u2192 \u0433: \u0413\u0435\u043D\u0440\u0456, \u0413\u0430\u0440\u0440\u0456; g \u2192 \u0491 \u043B\u0438\u0448\u0435 \u044F\u043A\u0449\u043E \u0442\u0430\u043A \u0437\u0430\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043D\u043E \u0432 \u043F\u0430\u0441\u043F\u043E\u0440\u0442\u0456; th \u2192 \u0442; w \u2192 \u0432/\u0443 \u0437\u0430 \u0442\u0440\u0430\u0434\u0438\u0446\u0456\u0454\u044E). \u0421\u0442\u0440\u043E\u0433\u043E \u0434\u043E\u0442\u0440\u0438\u043C\u0443\u0439\u0441\u044F \u0444\u043E\u0440\u043C \u0456\u0437 \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434\u0430\u0446\u044C\u043A\u043E\u0433\u043E \u043F\u0430\u0441\u043F\u043E\u0440\u0442\u0430 \u0442\u0435\u043A\u0441\u0442\u0443 \u2014 \u0446\u0435 \u0437\u0430\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043D\u0438\u0439 \u0433\u043B\u043E\u0441\u0430\u0440\u0456\u0439.
\u2022 \u0422\u0438\u0440\u0435 \u2014 \u0434\u043E\u0432\u0433\u0435 (\u2014), \u0434\u0435\u0444\u0456\u0441 \u043B\u0438\u0448\u0435 \u0432 \u0441\u043A\u043B\u0430\u0434\u043D\u0438\u0445 \u0441\u043B\u043E\u0432\u0430\u0445; \u0442\u0440\u0438 \u043A\u0440\u0430\u043F\u043A\u0438 \u2014 \xAB\u2026\xBB.
\u2022 \u0417\u0432\u0435\u0440\u0442\u0430\u043D\u043D\u044F \u0432 \u043A\u043B\u0438\u0447\u043D\u043E\u043C\u0443 \u0432\u0456\u0434\u043C\u0456\u043D\u043A\u0443, \u043A\u043E\u043B\u0438 \u0446\u0435 \u043F\u0440\u0438\u0440\u043E\u0434\u043D\u043E (\u043F\u0430\u043D\u0435 \u0414\u0436\u043E\u043D\u0441\u0435, \u043C\u0456\u0441\u0456\u0441 \u0421\u043C\u0456\u0442 \u2014 \u043D\u0435\u0437\u043C\u0456\u043D\u043D\u0456 \u0456\u043C\u0435\u043D\u043D\u0438\u043A\u0438 \u043D\u0435 \u0432\u0456\u0434\u043C\u0456\u043D\u044E\u044E\u0442\u044C\u0441\u044F).

\u0410\u041D\u0422\u0418\u041A\u0410\u041B\u042C\u041A\u041E\u0412\u0406 \u041F\u0420\u0410\u0412\u0418\u041B\u0410 (\u043F\u043E\u0440\u0443\u0448\u0435\u043D\u043D\u044F = \u043F\u043E\u043C\u0438\u043B\u043A\u0430):
\u2022 \xAB\u0431\u0443\u0442\u0438\xBB, \u0430 \u043D\u0435 \xAB\u044F\u0432\u043B\u044F\u0442\u0438\u0441\u044F/\u044F\u0432\u043B\u044F\u0454\u0442\u044C\u0441\u044F\xBB; \xAB\u043F\u0440\u043E\u0442\u044F\u0433\u043E\u043C\xBB, \u0430 \u043D\u0435 \xAB\u043D\u0430 \u043F\u0440\u043E\u0442\u044F\u0437\u0456\xBB; \xAB\u0431\u0440\u0430\u0442\u0438 \u0443\u0447\u0430\u0441\u0442\u044C\xBB, \u0430 \u043D\u0435 \xAB\u043F\u0440\u0438\u0439\u043C\u0430\u0442\u0438 \u0443\u0447\u0430\u0441\u0442\u044C\xBB; \xAB\u0432\u0436\u0438\u0432\u0430\u0442\u0438 \u0437\u0430\u0445\u043E\u0434\u0456\u0432\xBB, \u0430 \u043D\u0435 \xAB\u043F\u0440\u0438\u0439\u043C\u0430\u0442\u0438 \u043C\u0456\u0440\u0438\xBB; \xAB\u0437\u0431\u0456\u0433\u0430\u0442\u0438\u0441\u044F\xBB, \u0430 \u043D\u0435 \xAB\u0441\u043F\u0456\u0432\u043F\u0430\u0434\u0430\u0442\u0438\xBB; \xAB\u043D\u0430\u0441\u0442\u0443\u043F\u043D\u0438\u0439\xBB, \u0430 \u043D\u0435 \xAB\u0441\u043B\u0456\u0434\u0443\u044E\u0447\u0438\u0439\xBB; \xAB\u0449\u043E\u0434\u043E\xBB, \u0430 \u043D\u0435 \xAB\u043D\u0430 \u0440\u0430\u0445\u0443\u043D\u043E\u043A\xBB; \xAB\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E\xBB, \u0430 \u043D\u0435 \xAB\u0432\u0456\u0440\u043D\u043E\xBB (\u044F\u043A\u0449\u043E \u043D\u0435 \u043F\u0440\u043E \u0432\u0456\u0440\u043D\u0456\u0441\u0442\u044C); \xAB\u0431\u0440\u0430\u0442\u0438 \u0434\u043E \u0443\u0432\u0430\u0433\u0438\xBB, \u0430 \u043D\u0435 \xAB\u043F\u0440\u0438\u0439\u043C\u0430\u0442\u0438 \u0434\u043E \u0443\u0432\u0430\u0433\u0438\xBB; \xAB\u0443 \u0440\u0430\u0437\u0456\xBB, \u0430 \u043D\u0435 \xAB\u0432 \u0432\u0438\u043F\u0430\u0434\u043A\u0443\xBB; \xAB\u0437\u0430\u0432\u0434\u044F\u043A\u0438\xBB \u043B\u0438\u0448\u0435 \u043F\u0440\u043E \u043F\u043E\u0437\u0438\u0442\u0438\u0432\u043D\u0435.
\u2022 \u041D\u0435 \u0437\u043B\u043E\u0432\u0436\u0438\u0432\u0430\u0439 \u043F\u0430\u0441\u0438\u0432\u043E\u043C \u0456 \u0431\u0435\u0437\u043E\u0441\u043E\u0431\u043E\u0432\u0438\u043C\u0438 \u0444\u043E\u0440\u043C\u0430\u043C\u0438 \u043D\u0430 -\u043D\u043E/-\u0442\u043E, \u0434\u0435 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E \u043F\u0440\u0438\u0440\u043E\u0434\u043D\u0456\u0448\u0438\u0439 \u0430\u043A\u0442\u0438\u0432.
\u2022 \u0412\u0456\u0434\u0434\u0456\u0454\u0441\u043B\u0456\u0432\u043D\u0456 \u0456\u043C\u0435\u043D\u043D\u0438\u043A\u0438 (\xAB\u0437\u0434\u0456\u0439\u0441\u043D\u0435\u043D\u043D\u044F\xBB, \xAB\u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u043D\u044F\xBB) \u0437\u0430\u043C\u0456\u043D\u044F\u0439 \u0434\u0456\u0454\u0441\u043B\u043E\u0432\u0430\u043C\u0438.
\u2022 \u041D\u0435 \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434\u0430\u0439 \u043F\u0440\u0438\u0441\u0432\u0456\u0439\u043D\u0456 \u0437\u0430\u0439\u043C\u0435\u043D\u043D\u0438\u043A\u0438 \u043C\u0435\u0445\u0430\u043D\u0456\u0447\u043D\u043E (he put his hand in his pocket \u2192 \u0432\u0456\u043D \u0441\u0443\u043D\u0443\u0432 \u0440\u0443\u043A\u0443 \u0432 \u043A\u0438\u0448\u0435\u043D\u044E).
\u2022 \u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0441\u043B\u0456\u0432 \u2014 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0438\u0439: \u043D\u043E\u0432\u0435 (\u0440\u0435\u043C\u0430) \u0431\u043B\u0438\u0436\u0447\u0435 \u0434\u043E \u043A\u0456\u043D\u0446\u044F, \u0431\u0435\u0437 \u0430\u043D\u0433\u043B\u0456\u0439\u0441\u044C\u043A\u043E\u0457 \u0436\u043E\u0440\u0441\u0442\u043A\u043E\u0457 \u0441\u0445\u0435\u043C\u0438 \u043F\u0456\u0434\u043C\u0435\u0442\u2013\u043F\u0440\u0438\u0441\u0443\u0434\u043E\u043A\u2013\u0434\u043E\u0434\u0430\u0442\u043E\u043A.
\u2022 \u041D\u0435 \u043D\u0430\u0433\u0440\u043E\u043C\u0430\u0434\u0436\u0443\u0439 \xAB\u044F\u043A\u0438\u0439/\u044F\u043A\u0430/\u044F\u043A\u0435\xBB: \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0439 \u0434\u0456\u0454\u043F\u0440\u0438\u0441\u043B\u0456\u0432\u043D\u0438\u043A\u043E\u0432\u0456 \u0437\u0432\u043E\u0440\u043E\u0442\u0438, \u043E\u043A\u0440\u0435\u043C\u0456 \u0440\u0435\u0447\u0435\u043D\u043D\u044F, \u0441\u0443\u0440\u044F\u0434\u043D\u0456\u0441\u0442\u044C.
\u2022 \u0420\u0435\u043C\u0430\u0440\u043A\u0438 said/asked/replied \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0439 \u043F\u0440\u0438\u0440\u043E\u0434\u043D\u043E \u0439 \u0440\u0456\u0437\u043D\u043E\u043C\u0430\u043D\u0456\u0442\u043D\u043E, \u0430\u043B\u0435 \u0431\u0435\u0437 \u043D\u0430\u0434\u043C\u0456\u0440\u043D\u0438\u0445 \u043F\u0440\u0438\u043A\u0440\u0430\u0441; \u0442\u0430\u043C, \u0434\u0435 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E \u0440\u0435\u043C\u0430\u0440\u043A\u0430 \u0437\u0430\u0439\u0432\u0430, \u2014 \u043E\u043F\u0443\u0441\u043A\u0430\u0439.
\u2022 \u0410\u0440\u0442\u0438\u043A\u043B\u0456 \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0439 \u043B\u0438\u0448\u0435 \u043A\u043E\u043B\u0438 \u0432\u043E\u043D\u0438 \u043D\u0435\u0441\u0443\u0442\u044C \u0437\u043C\u0456\u0441\u0442 (\xAB\u044F\u043A\u0438\u0439\u0441\u044C\xBB, \xAB\u0442\u043E\u0439 \u0441\u0430\u043C\u0438\u0439\xBB).
\u2022 \u041D\u0435 \u0440\u0443\u0441\u0438\u0444\u0456\u043A\u0443\u0439 \u0456 \u043D\u0435 \u0441\u0443\u0440\u0436\u0438\u043A\u0443\u0439. \u041C\u043E\u0432\u043D\u0456 \u043E\u0441\u043E\u0431\u043B\u0438\u0432\u043E\u0441\u0442\u0456 \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0456\u0432 (\u043F\u0440\u043E\u0441\u0442\u043E\u0440\u0456\u0447\u0447\u044F, \u0436\u0430\u0440\u0433\u043E\u043D, \u0434\u0456\u0430\u043B\u0435\u043A\u0442) \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0439 \u0437\u0430\u0441\u043E\u0431\u0430\u043C\u0438 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u0457: \u0440\u043E\u0437\u043C\u043E\u0432\u043D\u043E\u044E \u043B\u0435\u043A\u0441\u0438\u043A\u043E\u044E, \u0441\u0438\u043D\u0442\u0430\u043A\u0441\u0438\u0441\u043E\u043C, \u0444\u0440\u0430\u0437\u0435\u043E\u043B\u043E\u0433\u0456\u0454\u044E, \u0430 \u043D\u0435 \u0448\u0442\u0443\u0447\u043D\u0438\u043C \xAB\u0441\u0443\u0440\u0436\u0438\u043A\u043E\u043C\xBB \u0447\u0438 \u0440\u0443\u0441\u0438\u0437\u043C\u0430\u043C\u0438, \u2014 \u0445\u0456\u0431\u0430 \u0449\u043E \u043F\u0430\u0441\u043F\u043E\u0440\u0442 \u043F\u0440\u044F\u043C\u043E \u0432\u0438\u043C\u0430\u0433\u0430\u0454 \u0456\u043D\u0430\u043A\u0448\u0435.
\u2022 \u0415\u043F\u043E\u0445\u0430\u043B\u044C\u043D\u0456 \u043E\u0434\u0438\u043D\u0438\u0446\u0456 (\u0444\u0443\u043D\u0442, \u043C\u0438\u043B\u044F, \u044F\u0440\u0434, \u0448\u0438\u043B\u0456\u043D\u0433, \u0434\u043E\u043B\u0430\u0440, \u0446\u0435\u043D\u0442) \u043D\u0435 \u043A\u043E\u043D\u0432\u0435\u0440\u0442\u0443\u0439.

\u0412\u0406\u0420\u041D\u0406\u0421\u0422\u042C:
\u2022 \u041D\u0456\u0447\u043E\u0433\u043E \u043D\u0435 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0439 \u0456 \u043D\u0435 \u0434\u043E\u0434\u0430\u0432\u0430\u0439 \u0432\u0456\u0434 \u0441\u0435\u0431\u0435. \u041D\u0435 \u043F\u043E\u044F\u0441\u043D\u044E\u0439 \u0440\u0435\u0430\u043B\u0456\u0457 \u0443 \u0442\u0435\u043A\u0441\u0442\u0456 \u0432\u0441\u0442\u0430\u0432\u043A\u0430\u043C\u0438, \u044F\u043A\u0449\u043E \u043F\u0430\u0441\u043F\u043E\u0440\u0442 \u043D\u0435 \u043A\u0430\u0436\u0435 \u0456\u043D\u0430\u043A\u0448\u0435; \u0441\u0443\u043C\u043D\u0456\u0432\u043D\u0456 \u0440\u0456\u0448\u0435\u043D\u043D\u044F \u0444\u0456\u043A\u0441\u0443\u044E\u0442\u044C\u0441\u044F \u043E\u043A\u0440\u0435\u043C\u043E, \u043D\u0435 \u0432 \u0442\u0435\u043A\u0441\u0442\u0456.
\u2022 \u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0439 \u0430\u0431\u0437\u0430\u0446\u043D\u0443 \u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u0443: \u0441\u0442\u0456\u043B\u044C\u043A\u0438 \u0436 \u0430\u0431\u0437\u0430\u0446\u0456\u0432, \u0443 \u0442\u043E\u043C\u0443 \u0436 \u043F\u043E\u0440\u044F\u0434\u043A\u0443.
\u2022 \u041C\u0435\u0442\u0430\u0444\u043E\u0440\u0438, \u043F\u043E\u0440\u0456\u0432\u043D\u044F\u043D\u043D\u044F, \u0456\u0434\u0456\u043E\u043C\u0438, \u0433\u0440\u0443 \u0441\u043B\u0456\u0432, \u0430\u043B\u044E\u0437\u0456\u0457 \u043F\u0435\u0440\u0435\u043A\u043B\u0430\u0434\u0430\u0439 \u0437\u0430 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0456\u044F\u043C\u0438 \u0437 \u043F\u0430\u0441\u043F\u043E\u0440\u0442\u0430: \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u043D\u044F \u043E\u0431\u0440\u0430\u0437\u0443, \u044F\u043A\u0449\u043E \u0432\u0456\u043D \u0437\u0440\u043E\u0437\u0443\u043C\u0456\u043B\u0438\u0439 \u0456 \u0436\u0438\u0432\u0438\u0439 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E; \u0437\u0430\u043C\u0456\u043D\u0430 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0438\u043C \u043E\u0431\u0440\u0430\u0437\u043E\u043C \u0456\u0437 \u0442\u0438\u043C \u0441\u0430\u043C\u0438\u043C \u0435\u0444\u0435\u043A\u0442\u043E\u043C; \u043F\u0435\u0440\u0435\u0444\u0440\u0430\u0437\u0443\u0432\u0430\u043D\u043D\u044F; \u043A\u043E\u043C\u043F\u0435\u043D\u0441\u0430\u0446\u0456\u044F \u0432 \u0441\u0443\u0441\u0456\u0434\u043D\u044C\u043E\u043C\u0443 \u043C\u0456\u0441\u0446\u0456. \u041D\u0435 \u043F\u0435\u0440\u0435\u0442\u0432\u043E\u0440\u044E\u0439 \u0436\u0438\u0432\u0456 \u043E\u0431\u0440\u0430\u0437\u0438 \u043D\u0430 \u043A\u0430\u043D\u0446\u0435\u043B\u044F\u0440\u0441\u044C\u043A\u0443 \u043F\u0440\u043E\u0437\u0443.
\u2022 \u0406\u0440\u043E\u043D\u0456\u044E, \u0433\u0443\u043C\u043E\u0440, \u043F\u0430\u0444\u043E\u0441, \u0440\u0438\u0442\u043C \u0440\u0435\u0447\u0435\u043D\u044C \u0456 \u0434\u043E\u0432\u0436\u0438\u043D\u0443 \u043F\u0435\u0440\u0456\u043E\u0434\u0456\u0432 \u0432\u0456\u0434\u0442\u0432\u043E\u0440\u044E\u0439 \u0442\u0430\u043A, \u044F\u043A \u043E\u043F\u0438\u0441\u0430\u043D\u043E \u0432 \u043F\u0430\u0441\u043F\u043E\u0440\u0442\u0456 \u0456\u0434\u0456\u043E\u0441\u0442\u0438\u043B\u044E.`;
